package cl.dynasty.nexusbeacon.platform.classic;
import org.bukkit.Material;import org.bukkit.configuration.ConfigurationSection;import org.bukkit.configuration.file.FileConfiguration;
final class ClassicPaymentResolver {private final FileConfiguration config;ClassicPaymentResolver(FileConfiguration config){this.config=config;}boolean levelEnabled(String id,int level){return config.getBoolean("effects."+id+".levels."+level+".enabled",true);}ClassicPaymentOption resolve(String id,String action,String key,int level){ConfigurationSection section=config.getConfigurationSection("effects."+id+".levels."+level+".costs."+action+".options."+key);if(section==null)section=config.getConfigurationSection("effects."+id+".costs."+action+".options."+key);if(section==null)return null;String raw=section.getString("type","").toUpperCase(java.util.Locale.ROOT);ClassicPaymentOption.Type type;try{type=ClassicPaymentOption.Type.valueOf(raw);}catch(IllegalArgumentException invalid){return null;}int amount=section.contains("amount")?section.getInt("amount"):section.getInt("amount-per-level",0)*level;if(amount<0)return null;Material material=null;if(type==ClassicPaymentOption.Type.ITEM){material=Material.matchMaterial(section.getString("material",""));if(material==null||amount<=0)return null;}if(type!=ClassicPaymentOption.Type.NONE&&amount<=0)return null;return new ClassicPaymentOption(type,amount,material);}}
